"use client";

import {FormEvent, useCallback, useEffect, useRef, useState} from "react";
import type {Dispatch, SetStateAction} from "react";
import dynamic from "next/dynamic";
import {Activity, ArrowDownToLine, ArrowRight, CircleAlert, Clapperboard, Cpu, Film, FolderOpen, LockKeyhole, Mic, Plus, Radio, RefreshCw, RotateCcw, Save, Sparkles, Upload} from "lucide-react";
import {AtelierHeader, atelierNav} from "@/components/atelier/atelier-header";
import type {AtelierView} from "@/components/atelier/atelier-header";
import {AtelierMediaStage} from "@/components/atelier/atelier-media-stage";
import {ClipMachine} from "@/components/clip-machine";
import {FlowDiagramEditor} from "@/components/flow-diagram-editor";
import {FootballEditor} from "@/components/football-editor";
import {MotionCardEditor} from "@/components/motion-card-editor";
import {TimedTranscriptEditor} from "@/components/timed-transcript-editor";
import {api} from "@/lib/api";
import {uploadLongVideo} from "@/lib/resumable-upload";
import {desktopChooseDataDir, desktopCreateBackup, desktopOpenLogs, desktopRestart, desktopRestoreBackup, desktopServices, desktopStart, desktopStop, runningInDesktop} from "@/lib/desktop";
import type {DesktopServices} from "@/lib/desktop";
import type {Asset, Channel, DoctorReport, Engine, GeoMunicipality, HardwareProfile, Job, OfficialProposal, Project, Scene, SetupState, SystemStatus, TimelineItem, TimelineResponse} from "@/lib/types";

type View = AtelierView;
type Dialog = "project" | "channel" | null;
const nav = atelierNav;
const TimelinePreview = dynamic(()=>import("./timeline-preview").then((module)=>module.TimelinePreview),{ssr:false});
const pilotChannels: Array<{name: string; slug: string; niche: string; default_engine: Engine}> = [
  {name: "Futebol em Foco", slug: "futebol-em-foco", niche: "Futebol", default_engine: "football"},
  {name: "Mundo em Mapas", slug: "mundo-em-mapas", niche: "Geografia", default_engine: "geo"},
  {name: "Pulso Musical", slug: "pulso-musical", niche: "Música", default_engine: "music"},
];
const ingestLabels: Record<string,string> = {PROXY_QUEUED:"Proxy na fila",READY:"Proxy pronto",WAVEFORM_FAILED:"Proxy pronto; forma de onda falhou",FAILED:"Proxy falhou"};
const stateLabels: Record<string, string> = {IDEA:"Ideia", SCRIPTED:"Plano pronto", RENDERING:"Renderizando", QC:"Vídeo pronto", APPROVED:"Aprovado", FAILED:"Falhou", QUEUED:"Na fila", RUNNING:"Em andamento", SUCCEEDED:"Concluído"};

export function ControlPanel() {
  const [view, setView] = useState<View>("studio");
  const [commandOpen, setCommandOpen] = useState(false);
  const [dialog, setDialog] = useState<Dialog>(null);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [jobs, setJobs] = useState<Job[]>([]);
  const [assets, setAssets] = useState<Asset[]>([]);
  const [system, setSystem] = useState<SystemStatus | null>(null);
  const [selected, setSelected] = useState<string | null>(null);
  const [session, setSession] = useState<{authenticated:boolean;login_required:boolean} | null>(null);
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [startupError, setStartupError] = useState<string | null>(null);
  const [setup, setSetup] = useState<SetupState | null>(null);
  const [hardware, setHardware] = useState<HardwareProfile | null>(null);

  const load = useCallback(async () => {
    try {
      const [newChannels, newProjects, newJobs, newSystem, newAssets] = await Promise.all([api.channels(),api.projects(),api.jobs(),api.system(),api.assets()]);
      setChannels(newChannels); setProjects(newProjects); setJobs(newJobs); setSystem(newSystem); setAssets(newAssets); setError(null);
    } catch (reason) { setError(message(reason)); }
  }, []);
  useEffect(() => { void api.session().then((value) => {setSession(value); if(value.authenticated) void load();}).catch((reason) => setStartupError(message(reason))); }, [load]);
  useEffect(() => {if(!session?.authenticated)return;void Promise.all([api.setup(),api.hardware()]).then(([state,profile])=>{setSetup(state);setHardware(profile);}).catch((reason)=>setStartupError(message(reason)));},[session]);
  useEffect(() => { if (!session?.authenticated) return; const interval = setInterval(() => {void load();}, 10000); return () => clearInterval(interval); }, [load,session]);
  const project = projects.find((item) => item.id === selected) ?? null;
  const openProject = (id: string) => {setSelected(id); setView("editor");};
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") {event.preventDefault();setCommandOpen((open) => !open);return;}
      if (event.key === "Escape") {setCommandOpen(false);return;}
      const index = Number(event.key) - 1;
      if ((event.altKey || event.ctrlKey || event.metaKey) && index >= 0 && index < nav.length) {event.preventDefault();setSelected(null);setView(nav[index].id);setCommandOpen(false);}
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);
  const run = async (action: () => Promise<unknown>) => {setBusy(true);setError(null);try {await action();await load();} catch(reason) {await load();setError(message(reason));} finally {setBusy(false);}};

  async function handleLogin(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    await run(async () => {await api.login(password);setSession({authenticated:true,login_required:true});setPassword("");});
  }
  async function handleLogout() { await run(async () => {await api.logout();setSession({authenticated:false,login_required:true});}); }
  async function createPilots() {
    await run(async () => {for (const pilot of pilotChannels) if (!channels.some((channel) => channel.slug === pilot.slug)) await api.createChannel(pilot);});
  }
  async function createChannel(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const data = new FormData(event.currentTarget);
    await run(async () => {await api.createChannel({name:data.get("name"),slug:data.get("slug"),niche:data.get("niche"),default_engine:data.get("engine")});setDialog(null);});
  }
  async function createProject(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const data = new FormData(event.currentTarget);
    await run(async () => {const created = await api.createProject({channel_id:data.get("channel"),title:data.get("title"),topic:data.get("topic"),format:data.get("format")});setDialog(null);openProject(created.id);await api.createPlan(created.id);});
  }

  if (!session || (session.authenticated && !setup)) return startupError?<div className="login-screen"><div className="login-card"><Brand/><h1>Não foi possível iniciar</h1><p>{startupError}</p>{runningInDesktop()&&<button className="button primary full" onClick={()=>void desktopRestart().then(()=>window.location.reload()).catch((reason)=>setStartupError(message(reason)))}>Reiniciar serviços locais</button>}</div></div>:<div className="loading">Carregando MediaGrid…</div>;
  if (!session.authenticated) return <div className="login-screen"><form onSubmit={handleLogin} className="login-card"><Brand/><h1>Acesse seu estúdio</h1><p>Entre com a senha de administrador para gerenciar seus canais e projetos.</p><Field label="Senha"><input type="password" autoComplete="current-password" value={password} onChange={(event) => setPassword(event.target.value)} required/></Field>{error && <Alert text={error}/>}<button className="button primary full" disabled={busy}><LockKeyhole size={16}/> Entrar</button></form></div>;
  if (!setup) return <div className="loading">Carregando configuração…</div>;
  if (!setup.complete) return <SetupWizard setup={setup} hardware={hardware} system={system} onComplete={setSetup}/>;

  const navigate = (next: View) => {setView(next);setSelected(null);};
  return <div className="app atelier-app">
    <AtelierHeader view={view} mode={system?.mode??null} loginRequired={session.login_required} onNavigate={navigate} onCommand={()=>setCommandOpen(true)} onRefresh={()=>void load()} onLogout={()=>void handleLogout()}/>
    <main className="content atelier-content"><div className="atelier-page-heading"><div className="eyebrow">{String(nav.findIndex((item)=>item.id===view)+1).padStart(2,"0")} — WORKSPACE / MEDIAGRID ATELIER</div><h1>{selected?project?.title:nav.find((item)=>item.id===view)?.label??"Biblioteca"}</h1></div>{error&&<Alert text={error}/>}
      {view==="studio"&&<AtelierStudio channels={channels} projects={projects} jobs={jobs} onPilots={createPilots} onCreate={()=>setDialog("project")} onProject={openProject} onNavigate={navigate} busy={busy}/>}
      {view==="editor"&&(project?<ProjectEditor key={project.id} project={project} isFootball={channels.find((channel)=>channel.id===project.channel_id)?.default_engine==="football"} assets={assets} jobs={jobs.filter((job)=>job.project_id===project.id)} busy={busy} onBack={()=>setSelected(null)} onRadar={()=>navigate("radar")} onRefresh={load} onRun={run}/>:<Production projects={projects} channels={channels} onProject={openProject} onCreate={()=>setDialog("project")}/>)}
      {view==="motion"&&<MotionLibrary projects={projects} onProject={openProject}/>}
      {view==="radar"&&<Radar projects={projects} channels={channels} busy={busy} onProject={openProject} onRun={run}/>}
      {view==="network"&&<Channels channels={channels} busy={busy} onCreate={()=>setDialog("channel")} onPilots={createPilots} onRun={run}/>}
      {view==="control"&&<><div className="atelier-toolbar"><button className="button" onClick={()=>navigate("library")}><FolderOpen size={15}/> Biblioteca local</button><button className="button" disabled={!channels.length} onClick={()=>setDialog("project")}><Plus size={15}/> Nova pauta</button></div><SystemView system={system} jobs={jobs} busy={busy} onRun={run}/></>}
      {view==="insights"&&<Insights channels={channels} projects={projects} jobs={jobs}/>}
      {view==="settings"&&<SettingsView setup={setup} hardware={hardware} system={system} onNavigate={navigate}/>}
      {view==="library"&&<><button className="button quiet back" onClick={()=>navigate("control")}>← Control Room</button><Library assets={assets} jobs={jobs} system={system} busy={busy} onRun={run}/></>}
    </main>
    {commandOpen&&<div className="modal-backdrop" onMouseDown={(event)=>{if(event.target===event.currentTarget)setCommandOpen(false);}}><div className="modal command-palette" role="dialog" aria-modal="true" aria-label="Navegação rápida"><div className="eyebrow">NAVEGAÇÃO RÁPIDA · CTRL/⌘ K · ALT+1–8</div>{nav.map(({id,label},index)=><button key={id} onClick={()=>{navigate(id);setCommandOpen(false);}}><span>{String(index+1).padStart(2,"0")}</span>{label}<ArrowRight size={15}/></button>)}<button onClick={()=>{navigate("library");setCommandOpen(false);}}><span>09</span>Biblioteca local<ArrowRight size={15}/></button></div></div>}
    {dialog && <div className="modal-backdrop" role="presentation" onMouseDown={(event)=>{if(event.target===event.currentTarget)setDialog(null);}}><form className="modal" onSubmit={dialog==="project"?createProject:createChannel}><div className="eyebrow">{dialog==="project"?"NOVA PRODUÇÃO":"NOVO CANAL"}</div><h2>{dialog==="project"?"Comece uma nova pauta":"Configure um canal"}</h2>{dialog==="project"?<><Field label="Canal"><select name="channel" required>{channels.map((channel)=><option key={channel.id} value={channel.id}>{channel.name}</option>)}</select></Field><Field label="Título"><input name="title" minLength={2} required placeholder="Ex.: O mapa que surpreendeu o mundo"/></Field><Field label="Pauta / briefing"><textarea name="topic" minLength={3} rows={5} required placeholder="Escreva 3 a 5 fatos ou trechos, um por linha, com pelo menos 20 caracteres cada"/></Field><p className="small-note">Com 3 a 5 linhas, o MediaGrid usa seu texto como narração editável. Com um tema curto, cria apenas uma estrutura para você completar. A pesquisa e a checagem de fatos continuam sob sua revisão.</p><Field label="Formato"><select name="format"><option value="vertical">Vertical · Reels / Shorts / TikTok</option><option value="horizontal">Horizontal · YouTube</option><option value="square">Quadrado · Card</option><option value="carousel">Carrossel</option></select></Field></>:<><Field label="Nome"><input name="name" minLength={2} required placeholder="Nome do canal"/></Field><Field label="Identificador"><input name="slug" pattern="[a-z0-9]+(-[a-z0-9]+)*" required placeholder="nome-do-canal"/></Field><div className="field-grid"><Field label="Nicho"><input name="niche" required placeholder="Ex.: Futebol"/></Field><Field label="Engine"><select name="engine"><option value="football">Futebol</option><option value="geo">Geografia</option><option value="music">Música</option><option value="clips">Cortes</option><option value="politics">Política</option><option value="trends">Virais / Trends</option></select></Field></div></>}<div className="modal-actions"><button className="button" type="button" onClick={()=>setDialog(null)}>Cancelar</button><button className="button primary" disabled={busy} type="submit"><Plus size={15}/> Criar</button></div></form></div>}
  </div>;
}

function SetupWizard({setup,hardware,system,onComplete}:{setup:SetupState;hardware:HardwareProfile|null;system:SystemStatus|null;onComplete:(value:SetupState)=>void}) {
  const [dataDir,setDataDir]=useState(setup.data_dir);
  const [mode,setMode]=useState<"recommended"|"custom">("recommended");
  const [profile,setProfile]=useState<HardwareProfile["recommended_profile"]>(hardware?.recommended_profile??"LIGHT");
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState<string|null>(null);
  useEffect(()=>{if(hardware)setProfile(hardware.recommended_profile);},[hardware]);
  const choose=async()=>{setBusy(true);setError(null);try{const runtime=await desktopChooseDataDir();if(runtime)setDataDir(runtime.data_dir);}catch(reason){setError(message(reason));}finally{setBusy(false);}};
  const finish=async()=>{setBusy(true);setError(null);try{onComplete(await api.completeSetup(mode==="recommended"?(hardware?.recommended_profile??"LIGHT"):profile));}catch(reason){setError(message(reason));}finally{setBusy(false);}};
  const modules=[
    {name:"MediaGrid Core",ready:system!==null},
    {name:"FFmpeg",ready:system?.ffmpeg===true},
    {name:"IA local (Ollama)",ready:system?.ollama==="CONNECTED"},
    {name:"Transcrição",ready:system?.transcription==="AVAILABLE"},
    {name:"Voz local",ready:system?.tts==="AVAILABLE"},
  ];
  return <div className="wizard-screen"><div className="wizard-card"><Brand/><div className="eyebrow">PRIMEIRA CONFIGURAÇÃO</div><h1>Seu estúdio começa aqui.</h1><p>Detectamos os recursos deste computador. O MediaGrid funcionará localmente e pode usar módulos opcionais quando estiverem instalados.</p>{error&&<Alert text={error}/>}<div className="wizard-grid"><div className="panel"><div className="panel-head"><div><h3>Computador</h3><p>Perfil calculado com o hardware detectado</p></div><Cpu size={20}/></div><div className="panel-body"><div className="wizard-facts"><span>CPU <strong>{hardware?.cpu??"Verificando…"}</strong></span><span>RAM <strong>{hardware?.ram_gb!=null?`${hardware.ram_gb} GB`:"Não detectada"}</strong></span><span>GPU <strong>{hardware?.gpu??"Não detectada"}</strong></span><span>VRAM <strong>{hardware?.vram_gb!=null?`${hardware.vram_gb} GB`:"Não detectada"}</strong></span><span>Armazenamento livre <strong>{hardware?.disk_free_gb!=null?`${hardware.disk_free_gb} GB`:"Verificando…"}</strong></span><span>CUDA <strong>{hardware?.cuda_available?"Disponível":"Não detectado"}</strong></span></div></div></div><div className="panel"><div className="panel-head"><div><h3>Serviços locais</h3><p>Ausências não impedem abrir o painel</p></div><Activity size={20}/></div><div className="panel-body"><div className="wizard-facts">{modules.map((item)=><span key={item.name}>{item.name}<Badge value={item.ready?"ONLINE":"OFFLINE"}/></span>)}</div></div></div></div><div className="panel wizard-options"><div className="panel-body"><Field label="Pasta dos dados"><div className="wizard-path"><strong>{dataDir}</strong>{runningInDesktop()&&<button className="button small" disabled={busy} onClick={()=>void choose()}>Escolher pasta</button>}</div></Field><div className="field-grid"><Field label="Instalação"><select value={mode} onChange={(event)=>setMode(event.target.value as "recommended"|"custom")}><option value="recommended">Recomendada · {hardware?.recommended_profile??"LIGHT"}</option><option value="custom">Personalizada</option></select></Field>{mode==="custom"&&<Field label="Perfil de desempenho"><select value={profile} onChange={(event)=>setProfile(event.target.value as HardwareProfile["recommended_profile"])}><option value="LIGHT">Light</option><option value="BALANCED">Balanced</option><option value="QUALITY">Quality</option><option value="HIGH_PERFORMANCE">High Performance</option></select></Field>}</div><p className="small-note">Modelos de IA grandes não são baixados automaticamente. Você poderá escolher o que instalar depois.</p><button className="button primary" disabled={busy||!hardware} onClick={()=>void finish()}><Sparkles size={16}/> Abrir MediaGrid</button></div></div></div></div>;
}

function Overview({channels,projects,jobs,system,onPilots,onCreate,onProject,onNavigate,busy}:{channels:Channel[];projects:Project[];jobs:Job[];system:SystemStatus|null;onPilots:()=>void;onCreate:()=>void;onProject:(id:string)=>void;onNavigate:(view:View)=>void;busy:boolean}) {return <>
  <section className="hero"><div><div className="eyebrow">SEU ESTÚDIO DE CONTEÚDO</div><h2>Uma operação de conteúdo.<br/>Todos os seus canais.</h2><p>Planeje, organize e produza em um só lugar. Comece pela sua pauta e acompanhe cada etapa com clareza.</p></div><div className="hero-actions">{!channels.length?<button className="button primary" onClick={onPilots} disabled={busy}><Sparkles size={17}/> Criar 3 canais piloto</button>:<button className="button primary" onClick={onCreate}><Plus size={17}/> Nova produção</button>}</div></section>
  <div className="metric-grid"><Metric label="Canais" value={String(channels.length)} detail="Identidades editoriais" icon={Radio}/><Metric label="Projetos" value={String(projects.length)} detail="Pautas cadastradas" icon={Clapperboard}/><Metric label="Vídeos prontos" value={String(projects.filter((item)=>item.status==="QC").length)} detail="Para baixar e revisar" icon={Film}/><Metric label="Sistema" value={system?.ffmpeg?"Ativo":"Verificar"} detail={system?.dry_run?"Publicação em modo de teste":"Publicação ativa"} icon={Cpu}/></div>
  <div className="section-heading"><div><h2>Seu trabalho recente</h2><p>Acompanhe a produção e retome de onde parou.</p></div><button className="button small" onClick={()=>onNavigate("editor")}>Abrir produção <ArrowRight size={14}/></button></div>
  <div className="two-col"><div className="panel"><div className="panel-head"><div><h3>Projetos</h3><p>Do briefing ao vídeo</p></div><span className="badge">{projects.length} no total</span></div>{projects.length?projects.slice(0,6).map((item)=><button key={item.id} className="row row-button" onClick={()=>onProject(item.id)}><span className="row-icon"><Film size={19}/></span><span className="row-main"><strong>{item.title}</strong><small>{channels.find((channel)=>channel.id===item.channel_id)?.name??"Canal"} · {item.format}</small></span><Badge value={item.status}/><ArrowRight size={16}/></button>):<Empty icon={Clapperboard} text="Nenhum projeto ainda. Crie os canais e depois sua primeira pauta."/>}</div><div className="panel"><div className="panel-head"><div><h3>Canais</h3><p>Operações em um mesmo lugar</p></div></div>{channels.length?channels.slice(0,5).map((channel)=><div key={channel.id} className="row"><span className="row-icon"><Radio size={18}/></span><span className="row-main"><strong>{channel.name}</strong><small>{channel.niche} · {channel.language}</small></span><span className="live-dot"/></div>):<Empty icon={Radio} text="Seus canais aparecerão aqui."/>}{jobs.some((job)=>job.status==="RUNNING")&&<p className="small-note side-note">Há renderizações em andamento. A tela atualiza automaticamente.</p>}</div></div>
</>}

function AtelierStudio({channels,projects,jobs,onPilots,onCreate,onProject,onNavigate,busy}:{channels:Channel[];projects:Project[];jobs:Job[];onPilots:()=>void;onCreate:()=>void;onProject:(id:string)=>void;onNavigate:(view:View)=>void;busy:boolean}) {
  const [selectedEngine,setSelectedEngine]=useState<Engine|null>(null);
  const engine=selectedEngine??channels.find((item)=>item.id===projects[0]?.channel_id)?.default_engine??channels[0]?.default_engine??"football";
  const [selectedSceneIndex,setSelectedSceneIndex]=useState(0);
  const worlds: Array<[Engine,string]> = [["football","Futebol"],["music","Música"],["politics","Política"],["geo","Geografia"],["trends","Virais"],["clips","Cortes"]];
  const channelIds = new Set(channels.filter((item)=>item.default_engine===engine).map((item)=>item.id));
  const active = projects.find((item)=>channelIds.has(item.channel_id));
  const channel = channels.find((item)=>item.id===active?.channel_id);
  const scenes = active?.plan?.scenes??[];
  const sceneIndex = Math.min(selectedSceneIndex, Math.max(0,scenes.length-1));
  const scene = scenes[sceneIndex];
  const activeStatus = active?.plan?.origin==="OUTLINE"?"Estrutura a completar":active?stateLabels[active.status]??active.status:"Sem projeto";
  return <>
    <div className="premium-page-heading"><div><div className="eyebrow">01 / CREATIVE WORKSPACE</div><h2>Uma ideia. Infinitas narrativas.</h2><p>Onde pesquisa, direção criativa e produção se encontram.</p></div><div className="premium-heading-actions"><span className="badge green">LOCAL</span><span className="badge">{activeStatus}</span>{active&&<span className="badge">{active.format.toUpperCase()}</span>}<button className="button primary" onClick={channels.length?onCreate:onPilots} disabled={busy}><Plus size={16}/>{channels.length?"Novo projeto":"Criar canais piloto"}</button></div></div>
    <div className="premium-studio-grid"><section className="premium-studio-main"><AtelierMediaStage project={active} channel={channel} engine={engine} scene={scene} sceneIndex={sceneIndex}/></section><aside className="premium-inspector"><div className="premium-inspector-title">DIRECTOR'S DESK <span>PROJETO LOCAL</span></div><div className="premium-property"><span>CANAL</span><strong>{channel?.name??"Selecione um canal"}</strong></div><div className="premium-property"><span>MOTOR</span><strong>{engine.toUpperCase()}</strong></div><div className="premium-property"><span>FORMATO</span><strong>{active?.format.toUpperCase()??"—"}</strong></div><div className="premium-property"><span>MOTION / CENA</span><strong>{scene?.transition??"—"}</strong></div><div className="premium-property"><span>ETAPA</span><strong>{activeStatus}</strong></div><div className="premium-property"><span>OUTPUT</span><strong>{active?.status==="QC"||active?.status==="APPROVED"?"MP4 local":"Ainda não renderizado"}</strong></div>{active?<button className="button primary" onClick={()=>onProject(active.id)}>Abrir no Editor <ArrowRight size={15}/></button>:channels.length?<button className="button primary" onClick={onCreate}>Criar pauta <ArrowRight size={15}/></button>:<button className="button primary" onClick={onPilots} disabled={busy}>Criar canais piloto <ArrowRight size={15}/></button>}<button className="button" onClick={()=>onNavigate("network")}>Configurar canais</button></aside></div>
    <div className="premium-scene-heading"><span>CENAS <small>{String(scenes.length).padStart(2,"0")}</small></span><span>{active?.plan?.target_duration_seconds??0}s PLANEJADOS / {scenes.length} CENAS</span></div><div className="premium-scenes" role="group" aria-label="Cenas do projeto">{scenes.length?scenes.map((item,index)=><button key={item.id} className={index===sceneIndex?"selected":""} onClick={()=>setSelectedSceneIndex(index)} aria-pressed={index===sceneIndex}><span>{String(index+1).padStart(2,"0")} / {item.visual_type}</span><strong>{item.on_screen_text||"Cena sem título"}</strong><small>{item.duration_seconds}s · {item.transition}</small></button>):<div className="premium-scenes-empty">Nenhuma cena neste motor. Crie uma pauta ou selecione outro motor.</div>}<button className="premium-scene-edit" onClick={()=>active?onProject(active.id):onCreate()} disabled={!active&&!channels.length}><Plus size={20}/>{active?"Editar cenas":"Nova pauta"}</button></div>
    <div className="world-picker"><span>MOTORES EDITORIAIS</span><div role="group" aria-label="Motor editorial">{worlds.map(([id,label])=><button key={id} className={engine===id?"active":""} onClick={()=>{setSelectedEngine(id);setSelectedSceneIndex(0);}} aria-pressed={engine===id}>{label}</button>)}</div></div>
    <div className="atelier-links"><button onClick={()=>onNavigate("editor")}><span>01 — EDITOR</span><strong>{projects.length} projetos locais</strong>↗</button><button onClick={()=>onNavigate("radar")}><span>02 — RADAR</span><strong>Pautas com revisão</strong>↗</button><button onClick={()=>onNavigate("network")}><span>03 — NETWORK</span><strong>{channels.length} canais configurados</strong>↗</button><button onClick={()=>onNavigate("control")}><span>04 — CONTROL</span><strong>{jobs.filter((job)=>job.status==="RUNNING").length} trabalhos ativos</strong>↗</button></div>
  </>;
}

function MotionLibrary({projects,onProject}:{projects:Project[];onProject:(id:string)=>void}) {const motions=[["Impacto","Entrada com escala e mola"],["Deslize","Entrada lateral com mola"],["Corte","Troca imediata de cena"],["Zoom","Ampliação progressiva"],["Fade","Entrada por opacidade"]];return <><div className="atelier-intro compact"><h2>Motion <span>Library.</span></h2><p>Cinco movimentos paramétricos são renderizados em Remotion. Escolha o movimento de cada cena no Editor.</p></div><div className="motion-grid">{motions.map(([name,description],index)=><div key={name}><span>{String(index+1).padStart(2,"0")} / REMOTION</span><strong>{name}</strong><p>{description}</p></div>)}</div><div className="atelier-note">PRESETS POR CANAL, DUPLICAÇÃO E VERSIONAMENTO AINDA NÃO IMPLEMENTADOS</div><div className="section-heading"><div><h2>Projetos para editar</h2><p>Abra um plano persistido, escolha os movimentos e renderize.</p></div></div><div className="atelier-list">{projects.length?projects.map((project)=><button key={project.id} onClick={()=>onProject(project.id)}><span>{project.format.toUpperCase()}</span><strong>{project.title}</strong><Badge value={project.status}/><ArrowRight size={16}/></button>):<p>Nenhum projeto ainda. Crie uma pauta no Studio.</p>}</div></>}

function Radar({projects,channels,busy,onProject,onRun}:{projects:Project[];channels:Channel[];busy:boolean;onProject:(id:string)=>void;onRun:(action:()=>Promise<unknown>)=>Promise<void>}) {
  const politicsChannels=channels.filter((channel)=>channel.default_engine==="politics");
  const [channelId,setChannelId]=useState("");
  const [query,setQuery]=useState("");
  const [year,setYear]=useState(new Date().getFullYear());
  const [results,setResults]=useState<OfficialProposal[]|null>(null);
  const [searching,setSearching]=useState(false);
  const [searchError,setSearchError]=useState<string|null>(null);
  const selectedChannel=politicsChannels.some((channel)=>channel.id===channelId)?channelId:(politicsChannels[0]?.id??"");
  const search=async(event:FormEvent<HTMLFormElement>)=>{
    event.preventDefault();setSearching(true);setSearchError(null);
    try{setResults(await api.politicsProposals(query.trim(),year));}
    catch(reason){setResults(null);setSearchError(message(reason));}
    finally{setSearching(false);}
  };
  const importProposal=(proposal:OfficialProposal)=>onRun(async()=>{const project=await api.importPoliticsProposal(selectedChannel,proposal.id);onProject(project.id);});
  return <><div className="atelier-intro compact"><h2>Radar <span>editorial.</span></h2><p>Consulte registros oficiais da Câmara e do IBGE para criar roteiros editáveis com fonte.</p></div>
    <div className="panel"><div className="panel-head"><div><h3>Política · Câmara dos Deputados</h3><p>Dados Abertos oficiais. Consulta feita somente ao clicar em buscar.</p></div><Radio size={19}/></div><div className="panel-body">
      <form onSubmit={(event)=>void search(event)}><div className="field-grid"><Field label="Assunto na ementa"><input value={query} onChange={(event)=>setQuery(event.target.value)} placeholder="Ex.: educação; vazio mostra os PLs recentes" minLength={3}/></Field><Field label="Ano"><input type="number" min="1990" max="2100" value={year} onChange={(event)=>setYear(Number(event.target.value))}/></Field></div><button className="button primary" disabled={searching} type="submit"><RefreshCw size={15}/> {searching?"Consultando…":"Buscar na Câmara"}</button></form>
      {searchError&&<Alert text={searchError}/>}
      {results!==null&&<><p className="small-note">{results.length} registros retornados pela API oficial. Ementa e situação exigem conferência humana antes da publicação.</p>{!results.length&&<p>Nenhuma proposição encontrada para esta busca.</p>}{results.map((proposal)=><div className="row" key={proposal.id}><span className="row-icon"><Radio size={17}/></span><span className="row-main"><strong>PL {proposal.number}/{proposal.year}</strong><small>{proposal.summary}</small><a href={proposal.source_url} target="_blank" rel="noopener noreferrer">Abrir registro na Câmara ↗</a></span><button className="button small" disabled={busy||!selectedChannel} onClick={()=>void importProposal(proposal)}>Criar roteiro</button></div>)}</>}
      {!politicsChannels.length?<p className="small-note">Crie um canal Política para importar uma pauta. <button className="button small" disabled={busy} onClick={()=>void onRun(async()=>{await api.createChannel({name:"Política em Foco",slug:"politica-em-foco",niche:"Política",default_engine:"politics"});})}>Criar canal Política</button></p>:<Field label="Canal para os roteiros"><select value={selectedChannel} onChange={(event)=>setChannelId(event.target.value)}>{politicsChannels.map((channel)=><option key={channel.id} value={channel.id}>{channel.name}</option>)}</select></Field>}
    </div></div><div className="atelier-note">Os dados vêm da Câmara no momento da consulta. A situação pode mudar; confira o registro antes de publicar.</div><GeoRadar channels={channels} busy={busy} onProject={onProject} onRun={onRun}/><div className="section-heading"><div><h2>Pautas em preparação</h2><p>Projetos salvos neste computador.</p></div></div><div className="atelier-list">{projects.length?projects.map((project)=><button key={project.id} onClick={()=>onProject(project.id)}><span>{project.created_at.slice(0,10)}</span><strong>{project.title}</strong><Badge value={project.status}/><ArrowRight size={16}/></button>):<p>Não há pautas locais. Pesquise acima ou crie uma no Studio.</p>}</div></>;
}

function GeoRadar({channels,busy,onProject,onRun}:{channels:Channel[];busy:boolean;onProject:(id:string)=>void;onRun:(action:()=>Promise<unknown>)=>Promise<void>}) {
  const geoChannels=channels.filter((channel)=>channel.default_engine==="geo");
  const [channelId,setChannelId]=useState("");
  const [query,setQuery]=useState("");
  const [results,setResults]=useState<GeoMunicipality[]|null>(null);
  const [searching,setSearching]=useState(false);
  const [searchError,setSearchError]=useState<string|null>(null);
  const selectedChannel=geoChannels.some((channel)=>channel.id===channelId)?channelId:(geoChannels[0]?.id??"");
  const search=async(event:FormEvent<HTMLFormElement>)=>{
    event.preventDefault();setSearching(true);setSearchError(null);
    try{setResults(await api.geoMunicipalities(query.trim()));}
    catch(reason){setResults(null);setSearchError(message(reason));}
    finally{setSearching(false);}
  };
  const importMunicipality=(municipality:GeoMunicipality)=>onRun(async()=>{const project=await api.importGeoMunicipality(selectedChannel,municipality.id);onProject(project.id);});
  return <><div className="panel"><div className="panel-head"><div><h3>Geo · municípios do IBGE</h3><p>Cadastro oficial de localidades. Consulta feita somente ao clicar em buscar.</p></div><Radio size={19}/></div><div className="panel-body">
    <form onSubmit={(event)=>void search(event)}><Field label="Nome do município"><input value={query} onChange={(event)=>setQuery(event.target.value)} placeholder="Ex.: São Paulo" minLength={3} maxLength={80} required/></Field><button className="button primary" disabled={searching} type="submit"><RefreshCw size={15}/> {searching?"Consultando…":"Buscar no IBGE"}</button></form>
    {searchError&&<Alert text={searchError}/>}
    {results!==null&&<><p className="small-note">{results.length} municípios encontrados. O roteiro usa apenas a divisão territorial retornada pelo IBGE; inclua e confira seus próprios visuais antes de publicar.</p>{!results.length&&<p>Nenhum município encontrado para esta busca.</p>}{results.map((municipality)=><div className="row" key={municipality.id}><span className="row-icon"><Radio size={17}/></span><span className="row-main"><strong>{municipality.name} · {municipality.state_code}</strong><small>Região imediata: {municipality.immediate_name} · {municipality.region_name}</small><a href={municipality.source_url} target="_blank" rel="noopener noreferrer">Abrir registro no IBGE ↗</a></span><button className="button small" disabled={busy||!selectedChannel} onClick={()=>void importMunicipality(municipality)}>Criar roteiro</button></div>)}</>}
    {!geoChannels.length?<p className="small-note">Crie um canal Geo para importar uma pauta. <button className="button small" disabled={busy} onClick={()=>void onRun(async()=>{await api.createChannel({name:"Mundo em Mapas",slug:"mundo-em-mapas",niche:"Geografia",default_engine:"geo"});})}>Criar canal Geo</button></p>:<Field label="Canal para os roteiros"><select value={selectedChannel} onChange={(event)=>setChannelId(event.target.value)}>{geoChannels.map((channel)=><option key={channel.id} value={channel.id}>{channel.name}</option>)}</select></Field>}
  </div></div><div className="atelier-note">A API do IBGE fornece localização administrativa, sem mapas licenciados ou indicadores populacionais neste fluxo.</div></>;
}

function Insights({channels,projects,jobs}:{channels:Channel[];projects:Project[];jobs:Job[]}) {return <><div className="atelier-intro compact"><h2>Insights <span>locais.</span></h2><p>Indicadores da sua produção registrados no MediaGrid.</p></div><div className="atelier-note">ANALYTICS DE YOUTUBE, TIKTOK E INSTAGRAM NÃO CONECTADOS · SEM MÉTRICAS INVENTADAS</div><div className="insights-grid"><div><span>CANAIS</span><strong>{channels.length}</strong></div><div><span>PROJETOS</span><strong>{projects.length}</strong></div><div><span>RENDERS CONCLUÍDOS</span><strong>{jobs.filter((job)=>job.job_type==="RENDER"&&job.status==="SUCCEEDED").length}</strong></div><div><span>TRABALHOS FALHOS</span><strong>{jobs.filter((job)=>job.status==="FAILED").length}</strong></div></div><div className="section-heading"><div><h2>Dados de plataformas</h2><p>Conecte contas por APIs oficiais em uma etapa futura. Até lá, o painel mostra apenas dados locais.</p></div></div></>}

function Production({projects,channels,onProject,onCreate}:{projects:Project[];channels:Channel[];onProject:(id:string)=>void;onCreate:()=>void}) {return <><div className="section-heading no-top"><div><h2>Produção</h2><p>Abra um projeto para editar seu plano, renderizar e baixar o vídeo.</p></div><button className="button primary" disabled={!channels.length} onClick={onCreate}><Plus size={16}/> Nova pauta</button></div><div className="panel">{projects.length?projects.map((project)=><button key={project.id} className="row row-button" onClick={()=>onProject(project.id)}><span className="row-icon"><Clapperboard size={19}/></span><span className="row-main"><strong>{project.title}</strong><small>{channels.find((channel)=>channel.id===project.channel_id)?.name??"Canal"} · {project.topic}</small></span><Badge value={project.status}/><ArrowRight size={16}/></button>):<Empty icon={Clapperboard} text="Ainda não há projetos. Crie uma pauta para começar."/>}</div></>}

function ProjectEditor({project,isFootball,assets,jobs,busy,onBack,onRadar,onRefresh,onRun}:{project:Project;isFootball:boolean;assets:Asset[];jobs:Job[];busy:boolean;onBack:()=>void;onRadar:()=>void;onRefresh:()=>Promise<void>;onRun:(action:()=>Promise<unknown>)=>Promise<void>}) {
  const [scenes,setScenes]=useState<Scene[]>(project.plan?.scenes??[]);
  const [timeline,setTimeline]=useState<TimelineResponse|null>(null);
  const [timelineError,setTimelineError]=useState<string|null>(null);
  const [hook,setHook]=useState(project.plan?.hook??"");
  const [angle,setAngle]=useState(project.plan?.angle??"");
  const [selectedScene,setSelectedScene]=useState(project.plan?.scenes[0]?.id??"");
  const [sourceUrls,setSourceUrls]=useState(project.plan?.review?.source_urls.join("\n")??project.plan?.source_refs?.map((source)=>source.url).join("\n")??"");
  const [reviewNotes,setReviewNotes]=useState(project.plan?.review?.notes??"");
  const [reviewCaption,setReviewCaption]=useState(project.plan?.review?.caption??project.plan?.hook??"");
  const [factsConfirmed,setFactsConfirmed]=useState(false);
  const [rightsConfirmed,setRightsConfirmed]=useState(false);
  useEffect(()=>{if(!scenes.length&&project.plan?.scenes.length){setScenes(project.plan.scenes);setHook(project.plan.hook);setAngle(project.plan.angle);setSelectedScene(project.plan.scenes[0].id);}},[project.plan,scenes.length]);
  useEffect(()=>{if(!project.edl)return;let cancelled=false;void api.timeline(project.id).then((value)=>{if(!cancelled){setTimeline(value);setTimelineError(null);}}).catch((reason)=>{if(!cancelled)setTimelineError(message(reason));});return()=>{cancelled=true;};},[project.id,project.updated_at]);
  const activeRender=jobs.some((job)=>job.job_type==="RENDER"&&(job.status==="QUEUED"||job.status==="RUNNING"));
  const edit=(index:number,field:keyof Scene,value:string|null)=>setScenes((current)=>current.map((scene,i)=>i===index?{...scene,[field]:field==="duration_seconds"||field==="clip_start_seconds"?Number(value):field==="clip_end_seconds"?(value===""?null:Number(value)):value}:scene));
  const chooseAsset=(index:number,assetId:string|null)=>setScenes((current)=>current.map((scene,i)=>i===index?{...scene,asset_id:assetId,clip_start_seconds:0,clip_end_seconds:null}:scene));
  const move=(index:number,direction:-1|1)=>setScenes((current)=>{const next=[...current];const target=index+direction;if(target<0||target>=next.length)return current;[next[index],next[target]]=[next[target],next[index]];return next;});
  const addScene=()=>{const scene:Scene={id:`manual-${crypto.randomUUID()}`,duration_seconds:5,narration:"",visual_type:"image",visual_query:"",on_screen_text:"",transition:"cut",asset_id:null,clip_start_seconds:0,clip_end_seconds:null};setScenes((current)=>[...current,scene]);setSelectedScene(scene.id);};
  const removeScene=(index:number)=>{if(scenes.length<=2)return;const next=scenes.filter((_,position)=>position!==index);setScenes(next);if(selectedScene===scenes[index].id)setSelectedScene(next[Math.min(index,next.length-1)].id);};
  const save=()=>onRun(async()=>{if(!timeline)throw new Error("Aguarde a timeline carregar antes de salvar.");const updated=await api.updatePlan(project.id,{scenes,hook,angle,expected_revision:timeline.revision,expected_legacy_sha256:timeline.legacy_sha256});setScenes(updated.plan?.scenes??scenes);setHook(updated.plan?.hook??hook);setAngle(updated.plan?.angle??angle);setTimeline(await api.timeline(project.id));});
  const render=()=>onRun(async()=>{await api.render(project.id);});
  const voice=()=>onRun(async()=>{await api.voice(project.id);});
  const voiceReady=project.voice_ready;
  const prepare=()=>onRun(async()=>{await api.createPlan(project.id);});
  const approve=()=>onRun(async()=>{await api.approveReview(project.id,{source_urls:sourceUrls.split(/\r?\n/).map((url)=>url.trim()).filter(Boolean),facts_confirmed:factsConfirmed,rights_confirmed:rightsConfirmed,notes:reviewNotes,caption:reviewCaption.trim()});});
  const unsaved=JSON.stringify(scenes)!==JSON.stringify(project.plan?.scenes)||hook!==project.plan?.hook||angle!==project.plan?.angle;
  const hasEmptyNarration=scenes.some((scene)=>!scene.narration.trim());
  return <><button className="button quiet back" onClick={onBack}>← Voltar à produção</button><div className="section-heading no-top"><div><div className="eyebrow">PROJETO / {project.format.toUpperCase()}</div><h2>{project.title}</h2><p>{project.topic}</p></div><Badge value={project.status}/></div>
    {isFootball&&<FootballEditor projectId={project.id} assets={assets}/>}
    {timeline&&<TimelineTracks timeline={timeline} assets={assets} selectedScene={selectedScene} onSelect={setSelectedScene}/>}
    {timeline&&project.plan?.origin!=="OUTLINE"&&<TimelinePreview projectId={project.id} timeline={timeline}/>}
    {timeline&&<OverlayEditor projectId={project.id} timeline={timeline} selectedScene={selectedScene} assets={assets} busy={busy} disabled={unsaved||activeRender} onRun={onRun} onSaved={setTimeline}/>}
    {timeline&&<MotionCardEditor projectId={project.id} timeline={timeline} selectedScene={selectedScene} busy={busy} disabled={unsaved||activeRender} onRun={onRun} onSaved={setTimeline}/>}
    {timeline&&<FlowDiagramEditor projectId={project.id} timeline={timeline} selectedScene={selectedScene} busy={busy} disabled={unsaved||activeRender} onRun={onRun} onSaved={setTimeline}/>}
    {voiceReady&&<VoiceWaveform projectId={project.id}/>}
    {timelineError&&<p className="small-note">Timeline: {timelineError}</p>}
    {project.plan?.source_refs?.length?<section className="panel"><div className="panel-head"><div><h3>Fontes do roteiro</h3><p>Dados consultados ao criar esta pauta. Confira a situação atual antes de publicar.</p></div></div><div className="panel-body">{project.plan.source_refs.map((source)=><p key={source.url}><a href={source.url} target="_blank" rel="noopener noreferrer">{source.title} ↗</a><span className="small-note"> · Consultado em {new Date(source.fetched_at).toLocaleString("pt-BR")}</span></p>)}</div></section>:null}
    {(project.status==="QC"||project.status==="APPROVED")&&<section className="panel review-panel"><div className="panel-head"><div><h3>Revisão humana e entrega</h3><p>Fontes e direitos devem ser confirmados por uma pessoa antes do pacote manual.</p></div><Badge value={project.status}/></div><div className="panel-body">{project.status==="APPROVED"?<><p className="small-note">Aprovado em {project.plan?.review?.approved_at?new Date(project.plan.review.approved_at).toLocaleString("pt-BR"):"data não informada"}. O pacote contém vídeo e manifesto; nenhuma plataforma foi acionada.</p><a className="button primary" href={api.exportPackage(project.id)} download><ArrowDownToLine size={15}/> Baixar pacote para publicação manual</a></>:<><Field label="Fontes verificadas (uma URL http/https por linha)"><textarea rows={3} value={sourceUrls} onChange={(event)=>setSourceUrls(event.target.value)} placeholder="https://fonte.example/documento"/></Field><Field label="Notas da revisão"><textarea rows={2} value={reviewNotes} onChange={(event)=>setReviewNotes(event.target.value)} placeholder="Registre o que foi conferido"/></Field><Field label="Legenda para publicação manual"><textarea rows={4} maxLength={2200} value={reviewCaption} onChange={(event)=>setReviewCaption(event.target.value)} placeholder="Escreva a legenda que acompanhará o vídeo no Instagram"/></Field><div className="review-checks"><label><input type="checkbox" checked={factsConfirmed} onChange={(event)=>setFactsConfirmed(event.target.checked)}/> Conferi os fatos e as fontes</label><label><input type="checkbox" checked={rightsConfirmed} onChange={(event)=>setRightsConfirmed(event.target.checked)}/> Conferi os direitos de mídia usados</label></div>{unsaved&&<p className="small-note">Há alterações não salvas no plano. Salve e renderize novamente antes da aprovação.</p>}<button className="button primary" disabled={busy||unsaved||!factsConfirmed||!rightsConfirmed||!sourceUrls.trim()||reviewNotes.trim().length<3||reviewCaption.trim().length<3} onClick={()=>void approve()}>Aprovar revisão</button></>}</div></section>}
    <div className="detail-grid"><div className="panel editor-panel"><div className="panel-head"><div><h3>Plano e timeline</h3><p>Edite e reordene cenas; salvar atualiza o EDL persistido.</p></div><span className="badge">{scenes.length} cenas</span></div><div className="panel-body">{project.plan?<><p className="small-note">{project.plan.origin==="OFFICIAL_SOURCE"?(project.plan.engine==="geo"?"Roteiro criado com a divisão territorial do IBGE. Confira os nomes atuais, escolha seus visuais e revise antes de publicar.":"Roteiro montado com a ementa e os metadados da Câmara. A tramitação pode mudar; confira a fonte oficial e edite o texto antes de publicar."):project.plan.origin==="BRIEF_BASED"?"Narração criada a partir das linhas do seu briefing, sem acrescentar fatos. Confira o texto e as fontes antes de renderizar.":project.plan.origin==="LOCAL_AI"?"Narração proposta pela IA local. Confira cada fato, fonte e direito antes de renderizar.":project.plan.origin==="MANUAL"?"Roteiro editado manualmente. Confira a narração e as fontes antes de renderizar.":"Esta é apenas uma estrutura automática com orientações editoriais. Escreva a narração de cada cena antes de gerar voz e vídeo."}</p>{project.plan.origin==="OUTLINE"&&project.plan.engine==="politics"&&<button className="button" onClick={onRadar}><Radio size={15}/> Buscar uma pauta oficial no Radar</button>}<div className="editor-timeline" role="group" aria-label="Timeline de cenas">{scenes.map((scene,index)=><button key={scene.id} className={selectedScene===scene.id?"active":""} onClick={()=>setSelectedScene(scene.id)}><span>{String(index+1).padStart(2,"0")} · {scene.visual_type}</span><strong>{scene.on_screen_text||"Sem título"}</strong><small>{scene.duration_seconds}s</small></button>)}</div><button className="button small" disabled={busy} onClick={addScene}><Plus size={14}/> Adicionar cena</button><Field label="Abertura"><input value={hook} onChange={(event)=>setHook(event.target.value)}/></Field><Field label="Ângulo editorial"><input value={angle} onChange={(event)=>setAngle(event.target.value)}/></Field>{project.plan.review_checks?.length>0&&<div className="atelier-note">REVISÃO ANTES DE PUBLICAR · {project.plan.review_checks.join(" · ")}</div>}{scenes.map((scene,index)=><div className={`scene-card ${selectedScene===scene.id?"selected":""}`} key={scene.id}><div className="scene-head"><span>CENA {String(index+1).padStart(2,"0")} · {scene.visual_type.toUpperCase()}</span><span><button className="scene-move" onClick={()=>move(index,-1)} disabled={index===0} aria-label={`Mover cena ${index+1} para cima`}>↑</button><button className="scene-move" onClick={()=>move(index,1)} disabled={index===scenes.length-1} aria-label={`Mover cena ${index+1} para baixo`}>↓</button><button className="scene-move" onClick={()=>removeScene(index)} disabled={busy||scenes.length<=2} aria-label={`Remover cena ${index+1}`}>×</button>{scene.duration_seconds}s</span></div><div className="field-grid"><Field label="Texto na tela"><input value={scene.on_screen_text} onChange={(event)=>edit(index,"on_screen_text",event.target.value)}/></Field><Field label="Duração (segundos)"><input type="number" min="0.1" max="60" step="0.1" value={scene.duration_seconds} onChange={(event)=>edit(index,"duration_seconds",event.target.value)}/></Field></div><Field label="Narração"><textarea rows={3} value={scene.narration} onChange={(event)=>edit(index,"narration",event.target.value)}/></Field><Field label="Busca visual / referência"><input value={scene.visual_query} onChange={(event)=>edit(index,"visual_query",event.target.value)}/></Field><Field label="Mídia da biblioteca"><select value={scene.asset_id??""} onChange={(event)=>chooseAsset(index,event.target.value||null)}><option value="">Tela de texto</option>{assets.filter((asset)=>["image/jpeg","image/png","image/webp","video/mp4"].includes(asset.media_type)).map((asset)=><option key={asset.id} value={asset.id}>{asset.name} · {asset.rights_status==="OWNED"?"arquivo próprio":asset.rights_status==="LICENSED"?"licenciado": "direitos pendentes"}</option>)}</select></Field>{scene.asset_id&&<SceneMediaPreview asset={assets.find((asset)=>asset.id===scene.asset_id)}/>}{assets.find((asset)=>asset.id===scene.asset_id)?.media_type==="video/mp4"&&<div className="field-grid"><Field label="Início do trecho (s)"><input type="number" min="0" max="21600" step="0.1" value={scene.clip_start_seconds??0} onChange={(event)=>edit(index,"clip_start_seconds",event.target.value)}/></Field><Field label="Fim do trecho (s)"><input type="number" min="0.1" max="21600" step="0.1" value={scene.clip_end_seconds??""} onChange={(event)=>edit(index,"clip_end_seconds",event.target.value)} placeholder="Até o fim do arquivo"/></Field></div>}{scene.asset_id&&<p className="small-note">{assets.find((asset)=>asset.id===scene.asset_id)?.rights_status==="OWNED"?"Arquivo próprio selecionado.":assets.find((asset)=>asset.id===scene.asset_id)?.rights_status==="LICENSED"&&assets.find((asset)=>asset.id===scene.asset_id)?.license_name?"Licença registrada.":"Confirme os direitos e registre a licença na Biblioteca antes de salvar."}</p>}<Field label="Movimento Remotion"><select value={scene.transition} onChange={(event)=>edit(index,"transition",event.target.value)}><option value="impact">Impacto</option><option value="slide">Deslize</option><option value="cut">Corte</option><option value="zoom">Zoom</option><option value="fade">Fade</option></select></Field></div>)}{unsaved&&<p className="small-note">Salve as alterações antes de gerar voz ou vídeo.</p>}{hasEmptyNarration&&<p className="small-note">Preencha a narração de todas as cenas antes de gerar voz ou vídeo.</p>}<div className="editor-actions"><button className="button" disabled={busy||!unsaved} onClick={()=>void save()}><Save size={16}/> Salvar alterações</button><button className="button primary" disabled={busy||unsaved||hasEmptyNarration||activeRender||project.plan?.origin==="OUTLINE"} onClick={()=>void render()}><Film size={16}/> Renderizar vídeo</button></div></>:<><Empty icon={Clapperboard} text="Este projeto ainda não possui plano. Gere a estrutura para começar."/><button className="button primary" disabled={busy} onClick={()=>void prepare()}><Sparkles size={16}/> Gerar estrutura de roteiro</button></>}</div></div>
    <div className="aside-stack"><div className="panel"><div className="panel-head"><div><h3>Saída</h3><p>Arquivos produzidos neste computador</p></div></div><div className="panel-body"><p className="small-note">Gere a narração antes do render para incluí-la no MP4. Revise fatos e direitos antes de publicar.</p><button className="button full" disabled={busy||unsaved||hasEmptyNarration||!project.script||project.plan?.origin==="OUTLINE"} onClick={()=>void voice()}><Mic size={16}/> Gerar voz local</button>{voiceReady&&<a className="button full" href={api.voiceFile(project.id)} download><ArrowDownToLine size={16}/> Baixar WAV</a>}{(project.status==="QC"||project.status==="APPROVED")?<><video className="editor-video" controls preload="metadata" src={api.output(project.id)} aria-label={`Prévia renderizada de ${project.title}`}/><a className="button primary full" href={api.output(project.id)} download><ArrowDownToLine size={16}/> Baixar MP4</a></>:<div className="output-wait"><Film size={23}/><span>Vídeo ainda não disponível</span></div>}</div></div><div className="panel"><div className="panel-head"><div><h3>Trabalhos</h3><p>Fila local de produção</p></div><button className="button small quiet" onClick={()=>void onRefresh()}><RefreshCw size={14}/></button></div>{jobs.length?jobs.map((job)=><div className="row" key={job.id}><span className="row-icon"><Cpu size={17}/></span><span className="row-main"><strong>{job.job_type} #{job.attempt}</strong><small>{job.error??new Date(job.created_at).toLocaleString("pt-BR")}</small></span><Badge value={job.status}/>{job.status==="FAILED"&&job.attempt<job.max_attempts&&<button className="button small" onClick={()=>void onRun(async()=>{await api.retry(job.id);})} title="Tentar novamente"><RotateCcw size={14}/></button>}</div>):<Empty icon={Cpu} text="Nenhum trabalho iniciado."/>}</div></div></div>
  </>;
}

function TimelineTracks({timeline,assets,selectedScene,onSelect}:{timeline:TimelineResponse;assets:Asset[];selectedScene:string;onSelect:(id:string)=>void}) {
  const duration=Math.max(1,timeline.edl.duration_ms);
  const labels:Record<string,string>={video:"Imagem / clipe",voice:"Narração",graphic:"Texto visual",caption:"Títulos / cartões",music:"Música",sfx:"Efeitos sonoros"};
  return <section className="panel timeline-v2"><div className="panel-head"><div><h3>Timeline persistida</h3><p>Trilhas da revisão {timeline.revision}; os blocos selecionam a cena correspondente.</p></div><span className="badge">{(duration/1000).toFixed(1)} s</span></div><div className="panel-body">{timeline.edl.tracks.map((track)=><div className="timeline-v2-row" key={track.id}><strong>{labels[track.kind]??track.kind}</strong><div className="timeline-v2-lane">{track.items.map((item)=><button key={item.id} className={selectedScene===item.params.scene_id?"active":""} style={{left:`${item.start_ms/duration*100}%`,width:`${item.duration_ms/duration*100}%`}} onClick={()=>item.params.scene_id&&onSelect(item.params.scene_id)} title={`${item.params.scene_id??item.id} · ${(item.start_ms/1000).toFixed(1)}–${((item.start_ms+item.duration_ms)/1000).toFixed(1)} s`}>{item.params.text||item.params.scene_id||assets.find((asset)=>asset.id===item.source_asset_id)?.name||item.id}</button>)}</div></div>)}<p className="small-note">{timeline.renderer==="timeline-v2"?"Camadas de título, som e clipes desta revisão são renderizadas no MP4. Revise o resultado completo antes de aprovar.":"Esta revisão usa o render de cenas atual; adicione camadas v2 no editor abaixo."} A prévia da revisão salva aparece abaixo.</p></div></section>;
}

type OverlayFrame={at_ms:number;x:number;y:number;opacity:number;scale:number};

function OverlayEditor({projectId,timeline,selectedScene,assets,busy,disabled,onRun,onSaved}:{projectId:string;timeline:TimelineResponse;selectedScene:string;assets:Asset[];busy:boolean;disabled:boolean;onRun:(action:()=>Promise<unknown>)=>Promise<void>;onSaved:(value:TimelineResponse)=>void}) {
  const [draft,setDraft]=useState<TimelineResponse["edl"]>(timeline.edl);
  const [selectedId,setSelectedId]=useState<string|null>(null);
  useEffect(()=>{setDraft(timeline.edl);},[timeline]);
  const track=draft.tracks.find((entry)=>entry.kind==="caption");
  const overlays=track?.items.filter((item)=>!(["motion_card_v1","flow_path_v1"].includes(item.preset??"")))??[];
  const selected=overlays.find((item)=>item.id===selectedId)??overlays[0];
  const frames=(selected?.params.keyframes??[]) as OverlayFrame[];
  const changed=JSON.stringify(draft)!==JSON.stringify(timeline.edl);
  const update=(id:string,callback:(item:TimelineItem)=>void)=>setDraft((current)=>{const next=structuredClone(current);const item=next.tracks.find((entry)=>entry.kind==="caption")?.items.find((entry)=>entry.id===id);if(item)callback(item);return next;});
  const add=()=>{const picture=draft.tracks.find((entry)=>entry.kind==="video")?.items.find((item)=>item.params.scene_id===selectedScene)??draft.tracks.find((entry)=>entry.kind==="video")?.items[0];if(!picture)return;const duration=Math.min(3000,picture.duration_ms);const id=`title-${crypto.randomUUID()}`;setDraft((current)=>{const next=structuredClone(current);let target=next.tracks.find((entry)=>entry.kind==="caption");if(!target){target={id:"kinetic-titles",kind:"caption",items:[]};next.tracks.push(target);}target.items.push({id,start_ms:picture.start_ms,duration_ms:duration,z_index:10,source_asset_id:null,source_in_ms:null,source_out_ms:null,speed:1,preset:"kinetic_title_v1",params:{text:"Novo título",color:"#dcf769",keyframes:[{at_ms:0,x:.5,y:.78,opacity:0,scale:.85},{at_ms:Math.min(600,duration-34),x:.5,y:.78,opacity:1,scale:1},{at_ms:duration,x:.5,y:.78,opacity:1,scale:1}]}});return next;});setSelectedId(id);};
  const remove=()=>{if(!selected)return;setDraft((current)=>{const next=structuredClone(current);const target=next.tracks.find((entry)=>entry.kind==="caption");if(target)target.items=target.items.filter((item)=>item.id!==selected.id);return next;});setSelectedId(null);};
  const updateFrame=(index:number,key:keyof OverlayFrame,value:number)=>{if(!selected)return;update(selected.id,(item)=>{const next=structuredClone(item.params.keyframes as OverlayFrame[]);next[index]={...next[index],[key]:value};item.params.keyframes=next;});};
  const save=()=>onRun(async()=>{await api.updateTimeline(projectId,{expected_revision:timeline.revision,expected_legacy_sha256:timeline.legacy_sha256,edl:draft});onSaved(await api.timeline(projectId));});
  return <section className="panel overlay-editor"><div className="panel-head"><div><h3>Camadas da timeline</h3><p>Títulos, música, efeitos e clipes locais salvos no EDL v2 e renderizados no vídeo.</p></div><button className="button small" disabled={busy||disabled} onClick={add}><Plus size={14}/> Adicionar título</button></div><div className="panel-body">{overlays.length?<><div className="overlay-list">{overlays.map((item)=><button key={item.id} className={`button small ${selected?.id===item.id?"selected":""}`} onClick={()=>setSelectedId(item.id)}>{String(item.params.text??"Título")}</button>)}</div>{selected&&<><div className="field-grid"><Field label="Texto"><input maxLength={180} value={String(selected.params.text??"")} onChange={(event)=>update(selected.id,(item)=>{item.params.text=event.target.value;})}/></Field><Field label="Cor"><input type="color" value={String(selected.params.color??"#dcf769")} onChange={(event)=>update(selected.id,(item)=>{item.params.color=event.target.value;})}/></Field></div><div className="field-grid"><Field label="Início (s)"><input type="number" min="0" step="0.1" value={selected.start_ms/1000} onChange={(event)=>update(selected.id,(item)=>{item.start_ms=Math.round(Number(event.target.value)*1000);})}/></Field><Field label="Duração (s)"><input type="number" min="0.2" step="0.1" value={selected.duration_ms/1000} onChange={(event)=>update(selected.id,(item)=>{const duration=Math.round(Number(event.target.value)*1000);item.duration_ms=duration;const keyframes=item.params.keyframes as OverlayFrame[];keyframes[keyframes.length-1].at_ms=duration;})}/></Field></div>{frames.map((frame,index)=><div className="overlay-keyframe" key={index}><strong>Keyframe {index===0?"inicial":index===frames.length-1?"final":"intermediário"} · {(frame.at_ms/1000).toFixed(1)} s</strong><div className="field-grid"><Field label="X (0–1)"><input type="number" min="0" max="1" step="0.05" value={frame.x} onChange={(event)=>updateFrame(index,"x",Number(event.target.value))}/></Field><Field label="Y (0–1)"><input type="number" min="0" max="1" step="0.05" value={frame.y} onChange={(event)=>updateFrame(index,"y",Number(event.target.value))}/></Field><Field label="Opacidade"><input type="number" min="0" max="1" step="0.05" value={frame.opacity} onChange={(event)=>updateFrame(index,"opacity",Number(event.target.value))}/></Field><Field label="Escala"><input type="number" min="0.25" max="4" step="0.05" value={frame.scale} onChange={(event)=>updateFrame(index,"scale",Number(event.target.value))}/></Field></div></div>)}<button className="button small" disabled={busy||disabled} onClick={remove}>Remover título</button></>}</>:<p className="small-note">Nenhum título adicional. O texto das cenas continua no render tradicional.</p>}<SoundControls draft={draft} setDraft={setDraft} assets={assets} busy={busy} disabled={disabled}/><VideoLayerControls draft={draft} setDraft={setDraft} assets={assets} busy={busy} disabled={disabled}/>{changed&&<p className="small-note">Salve a timeline e renderize novamente para ver as camadas. A saída anterior será invalidada.</p>}<button className="button primary" disabled={busy||disabled||!changed||overlays.some((item)=>!String(item.params.text??"").trim())} onClick={()=>void save()}><Save size={15}/> Salvar timeline v2</button></div></section>;
}

function SoundControls({draft,setDraft,assets,busy,disabled}:{draft:TimelineResponse["edl"];setDraft:Dispatch<SetStateAction<TimelineResponse["edl"]>>;assets:Asset[];busy:boolean;disabled:boolean}) {
  const available=assets.filter((asset)=>["audio/wav","audio/x-wav","audio/mpeg"].includes(asset.media_type)&&(asset.rights_status==="OWNED"||(asset.rights_status==="LICENSED"&&asset.license_name)));
  const [assetId,setAssetId]=useState("");
  const [kind,setKind]=useState<"music"|"sfx">("music");
  const [selectedId,setSelectedId]=useState<string|null>(null);
  const sounds=draft.tracks.filter((track)=>track.kind==="music"||track.kind==="sfx").flatMap((track)=>track.items);
  const selected=sounds.find((item)=>item.id===selectedId)??sounds[0];
  const update=(callback:(item:TimelineItem)=>void)=>{if(!selected)return;setDraft((current)=>{const next=structuredClone(current);const item=next.tracks.flatMap((track)=>track.items).find((entry)=>entry.id===selected.id);if(item)callback(item);return next;});};
  const add=()=>{if(!assetId)return;const id=`sound-${crypto.randomUUID()}`;setDraft((current)=>{const next=structuredClone(current);let track=next.tracks.find((entry)=>entry.kind===kind);if(!track){track={id:`local-${kind}`,kind,items:[]};next.tracks.push(track);}track.items.push({id,start_ms:0,duration_ms:Math.min(1000,next.duration_ms),z_index:0,source_asset_id:assetId,source_in_ms:null,source_out_ms:null,speed:1,preset:"sound_v1",params:{gain:kind==="music"?0.2:0.5,fade_in_ms:0,fade_out_ms:0,loop:false}});return next;});setSelectedId(id);};
  const remove=()=>{if(!selected)return;setDraft((current)=>{const next=structuredClone(current);for(const track of next.tracks){track.items=track.items.filter((item)=>item.id!==selected.id);}return next;});setSelectedId(null);};
  return <div className="sound-controls"><h4>Som da biblioteca</h4><p className="small-note">Use apenas WAV/MP3 próprio ou licenciado. O volume da música é baixo por padrão; ouça o mix completo após renderizar.</p><div className="field-grid"><Field label="Arquivo de áudio"><select value={assetId} onChange={(event)=>setAssetId(event.target.value)}><option value="">Escolha um arquivo autorizado</option>{available.map((asset)=><option key={asset.id} value={asset.id}>{asset.name}</option>)}</select></Field><Field label="Trilha"><select value={kind} onChange={(event)=>setKind(event.target.value as "music"|"sfx")}><option value="music">Música</option><option value="sfx">Efeito sonoro</option></select></Field></div><button className="button small" disabled={busy||disabled||!assetId} onClick={add}><Plus size={14}/> Adicionar som</button>{!available.length&&<p className="small-note">Importe um WAV ou MP3 e registre os direitos na Biblioteca para habilitar a trilha.</p>}{sounds.length>0&&<><div className="overlay-list">{sounds.map((item)=><button key={item.id} className={`button small ${selected?.id===item.id?"selected":""}`} onClick={()=>setSelectedId(item.id)}>{draft.tracks.find((track)=>track.items.some((entry)=>entry.id===item.id))?.kind==="sfx"?"Efeito":"Música"} · {assets.find((asset)=>asset.id===item.source_asset_id)?.name??"Áudio"} · {(item.start_ms/1000).toFixed(1)} s</button>)}</div>{selected&&<><audio controls preload="metadata" src={api.assetFile(String(selected.source_asset_id))} aria-label="Ouvir arquivo da trilha"/><div className="field-grid"><Field label="Início na timeline (s)"><input type="number" min="0" step="0.1" value={selected.start_ms/1000} onChange={(event)=>update((item)=>{item.start_ms=Math.round(Number(event.target.value)*1000);})}/></Field><Field label="Duração (s)"><input type="number" min="0.1" step="0.1" value={selected.duration_ms/1000} onChange={(event)=>update((item)=>{item.duration_ms=Math.round(Number(event.target.value)*1000);})}/></Field></div><div className="field-grid"><Field label="Volume (0–1)"><input type="number" min="0.01" max="1" step="0.05" value={Number(selected.params.gain??0.2)} onChange={(event)=>update((item)=>{item.params.gain=Number(event.target.value);})}/></Field><Field label="Fade in (s)"><input type="number" min="0" step="0.1" value={Number(selected.params.fade_in_ms??0)/1000} onChange={(event)=>update((item)=>{item.params.fade_in_ms=Math.round(Number(event.target.value)*1000);})}/></Field><Field label="Fade out (s)"><input type="number" min="0" step="0.1" value={Number(selected.params.fade_out_ms??0)/1000} onChange={(event)=>update((item)=>{item.params.fade_out_ms=Math.round(Number(event.target.value)*1000);})}/></Field></div><label className="small-note"><input type="checkbox" checked={Boolean(selected.params.loop)} onChange={(event)=>update((item)=>{item.params.loop=event.target.checked;})}/> Repetir arquivo até o fim do item</label><button className="button small" disabled={busy||disabled} onClick={remove}>Remover som</button></>}</>}</div>;
}

function VideoLayerControls({draft,setDraft,assets,busy,disabled}:{draft:TimelineResponse["edl"];setDraft:Dispatch<SetStateAction<TimelineResponse["edl"]>>;assets:Asset[];busy:boolean;disabled:boolean}) {
  const available=assets.filter((asset)=>asset.media_type==="video/mp4"&&(asset.rights_status==="OWNED"||(asset.rights_status==="LICENSED"&&asset.license_name)));
  const [assetId,setAssetId]=useState("");
  const [selectedId,setSelectedId]=useState<string|null>(null);
  const layers=draft.tracks.filter((track)=>track.kind==="video"&&track.id!=="picture").flatMap((track)=>track.items);
  const selected=layers.find((item)=>item.id===selectedId)??layers[0];
  const update=(callback:(item:TimelineItem)=>void)=>{if(!selected)return;setDraft((current)=>{const next=structuredClone(current);const item=next.tracks.flatMap((track)=>track.items).find((entry)=>entry.id===selected.id);if(item)callback(item);return next;});};
  const add=()=>{if(!assetId)return;const id=`cutaway-${crypto.randomUUID()}`;setDraft((current)=>{const next=structuredClone(current);let track=next.tracks.find((entry)=>entry.kind==="video"&&entry.id!=="picture");if(!track){track={id:"cutaways",kind:"video",items:[]};next.tracks.push(track);}const duration=Math.min(1000,next.duration_ms);track.items.push({id,start_ms:0,duration_ms:duration,z_index:5,source_asset_id:assetId,source_in_ms:0,source_out_ms:duration,speed:1,preset:"video_overlay_v1",params:{focus_x:0.5,focus_y:0.5,opacity:1}});return next;});setSelectedId(id);};
  const remove=()=>{if(!selected)return;setDraft((current)=>{const next=structuredClone(current);for(const track of next.tracks){if(track.kind==="video"&&track.id!=="picture")track.items=track.items.filter((item)=>item.id!==selected.id);}return next;});setSelectedId(null);};
  return <div className="video-layer-controls"><h4>Clipe sobre as cenas</h4><p className="small-note">MP4 próprio ou licenciado, sem áudio de origem. Escolha o intervalo e confira o enquadramento após renderizar.</p><Field label="MP4 da biblioteca"><select value={assetId} onChange={(event)=>setAssetId(event.target.value)}><option value="">Escolha um MP4 autorizado</option>{available.map((asset)=><option key={asset.id} value={asset.id}>{asset.name}</option>)}</select></Field><button className="button small" disabled={busy||disabled||!assetId} onClick={add}><Plus size={14}/> Adicionar clipe</button>{!available.length&&<p className="small-note">Importe um MP4 e registre os direitos na Biblioteca para habilitar esta camada.</p>}{layers.length>0&&<><div className="overlay-list">{layers.map((item)=><button key={item.id} className={`button small ${selected?.id===item.id?"selected":""}`} onClick={()=>setSelectedId(item.id)}>{assets.find((asset)=>asset.id===item.source_asset_id)?.name??"MP4"} · {(item.start_ms/1000).toFixed(1)} s</button>)}</div>{selected&&<><video controls muted preload="metadata" src={assets.find((asset)=>asset.id===selected.source_asset_id)?.metadata_json.proxy_sha256?api.assetProxy(String(selected.source_asset_id)):api.assetFile(String(selected.source_asset_id))} aria-label="Prévia do arquivo do clipe"/><div className="field-grid"><Field label="Início na timeline (s)"><input type="number" min="0" step="0.1" value={selected.start_ms/1000} onChange={(event)=>update((item)=>{item.start_ms=Math.round(Number(event.target.value)*1000);})}/></Field><Field label="Duração (s)"><input type="number" min="0.1" step="0.1" value={selected.duration_ms/1000} onChange={(event)=>update((item)=>{const duration=Math.round(Number(event.target.value)*1000);item.duration_ms=duration;item.source_out_ms=(item.source_in_ms??0)+duration;})}/></Field><Field label="Início no MP4 (s)"><input type="number" min="0" step="0.1" value={(selected.source_in_ms??0)/1000} onChange={(event)=>update((item)=>{const start=Math.round(Number(event.target.value)*1000);item.source_in_ms=start;item.source_out_ms=start+item.duration_ms;})}/></Field></div><div className="field-grid"><Field label="Foco X (0–1)"><input type="number" min="0" max="1" step="0.05" value={Number(selected.params.focus_x??0.5)} onChange={(event)=>update((item)=>{item.params.focus_x=Number(event.target.value);})}/></Field><Field label="Foco Y (0–1)"><input type="number" min="0" max="1" step="0.05" value={Number(selected.params.focus_y??0.5)} onChange={(event)=>update((item)=>{item.params.focus_y=Number(event.target.value);})}/></Field><Field label="Opacidade (0–1)"><input type="number" min="0.01" max="1" step="0.05" value={Number(selected.params.opacity??1)} onChange={(event)=>update((item)=>{item.params.opacity=Number(event.target.value);})}/></Field></div><button className="button small" disabled={busy||disabled} onClick={remove}>Remover clipe</button></>}</>}</div>;
}

function VoiceWaveform({projectId}:{projectId:string}) {
  const canvas=useRef<HTMLCanvasElement>(null);
  const [error,setError]=useState<string|null>(null);
  const url=api.voiceFile(projectId);
  useEffect(()=>{const controller=new AbortController();let audioContext:AudioContext|null=null;void (async()=>{try{const response=await fetch(url,{signal:controller.signal});if(!response.ok)throw new Error(`WAV indisponível (${response.status})`);const bytes=await response.arrayBuffer();if(controller.signal.aborted)return;audioContext=new AudioContext();const audio=await audioContext.decodeAudioData(bytes);if(controller.signal.aborted)return;const element=canvas.current;if(!element)return;const context=element.getContext("2d");if(!context)return;const samples=audio.getChannelData(0);const width=element.width;const height=element.height;context.clearRect(0,0,width,height);context.fillStyle="#dcf769";for(let x=0;x<width;x++){const start=Math.floor(x*samples.length/width);const end=Math.min(samples.length,Math.floor((x+1)*samples.length/width));let peak=0;for(let i=start;i<end;i++)peak=Math.max(peak,Math.abs(samples[i]));const size=Math.max(2,peak*(height-8));context.fillRect(x,(height-size)/2,1,size);}}catch(reason){if(!controller.signal.aborted)setError(message(reason));}finally{if(audioContext)void audioContext.close();}})();return()=>controller.abort();},[url]);
  return <section className="panel voice-waveform"><div className="panel-head"><div><h3>Forma de onda da voz</h3><p>Áudio local gerado para este roteiro; ouça antes de renderizar.</p></div></div><div className="panel-body"><canvas ref={canvas} width={900} height={90} aria-label="Forma de onda da narração"/><audio controls preload="metadata" src={url} aria-label="Ouvir narração"/>{error&&<p className="small-note">{error}</p>}</div></section>;
}

function SceneMediaPreview({asset}:{asset?:Asset}) {
  if(!asset)return null;
  const url=asset.metadata_json.proxy_sha256?api.assetProxy(asset.id):api.assetFile(asset.id);
  return <div className="scene-media-preview">{asset.media_type.startsWith("image/")?<img src={url} alt={`Prévia de ${asset.name}`}/>:<video src={url} controls preload="metadata" aria-label={`Prévia de ${asset.name}`}/>}<span>{asset.name}</span></div>;
}

function Library({assets,jobs,system,busy,onRun}:{assets:Asset[];jobs:Job[];system:SystemStatus|null;busy:boolean;onRun:(action:()=>Promise<unknown>)=>Promise<void>}) {
  const [selected,setSelected]=useState<File|null>(null);
  const [uploadProgress,setUploadProgress]=useState<{name:string;received:number;total:number}|null>(null);
  const [lastProxyJob,setLastProxyJob]=useState<string|null>(null);
  const [rights,setRights]=useState("UNKNOWN");
  const [creator,setCreator]=useState("");
  const [sourceUrl,setSourceUrl]=useState("");
  const [licenseName,setLicenseName]=useState("");
  const [commercialUse,setCommercialUse]=useState(false);
  const [editingRights,setEditingRights]=useState<Asset|null>(null);
  const [editStatus,setEditStatus]=useState("UNKNOWN");
  const [editCreator,setEditCreator]=useState("");
  const [editSourceUrl,setEditSourceUrl]=useState("");
  const [editLicense,setEditLicense]=useState("");
  const [editCommercial,setEditCommercial]=useState(false);
  const [transcript,setTranscript]=useState<string|null>(null);
  const [timedAsset,setTimedAsset]=useState<Asset|null>(null);
  const [clipAsset,setClipAsset]=useState<Asset|null>(null);
  const [transcriptName,setTranscriptName]=useState("");
  const upload=()=>onRun(async()=>{if(!selected)return;if(selected.name.toLowerCase().endsWith(".mp4")){
    const result=await uploadLongVideo(selected,{rights_status:rights,creator:creator||null,source_url:sourceUrl||null,license_name:licenseName||null,commercial_use:commercialUse},
      (state)=>setUploadProgress({name:state.name,received:state.received_bytes,total:state.size_bytes}));
    setLastProxyJob(result.proxy_job_id);setUploadProgress(null);
  }else{const form=new FormData();form.append("file",selected);form.append("rights_status",rights);form.append("creator",creator);form.append("source_url",sourceUrl);form.append("license_name",licenseName);form.append("commercial_use",String(commercialUse));await api.uploadAsset(form);}
    setSelected(null);});
  const openRights=(asset:Asset)=>{setEditingRights(asset);setEditStatus(asset.rights_status);setEditCreator(asset.creator??"");setEditSourceUrl(asset.source_url??"");setEditLicense(asset.license_name??"");setEditCommercial(asset.commercial_use);};
  const saveRights=()=>onRun(async()=>{if(!editingRights)return;await api.updateAssetRights(editingRights.id,{rights_status:editStatus,creator:editCreator||null,source_url:editSourceUrl||null,license_name:editLicense||null,commercial_use:editCommercial});setEditingRights(null);});
  const showTranscript=(asset:Asset)=>onRun(async()=>{setTranscript(await api.transcript(asset.id));setTranscriptName(asset.name);});
  return <><div className="section-heading no-top"><div><h2>Biblioteca local</h2><p>Guarde arquivos no seu computador e registre os direitos de uso.</p></div><span className="badge">{assets.length} arquivos</span></div>
    <div className="panel"><div className="panel-head"><div><h3>Adicionar arquivo</h3><p>MP4 com retomada até 20 GiB; demais arquivos até 500 MB</p></div><Upload size={20}/></div><div className="panel-body"><div className="field-grid"><Field label="Arquivo"><input type="file" onChange={(event)=>setSelected(event.target.files?.[0]??null)}/></Field><Field label="Direitos"><select value={rights} onChange={(event)=>setRights(event.target.value)}><option value="UNKNOWN">A verificar</option><option value="OWNED">Meu arquivo</option><option value="LICENSED">Licenciado</option><option value="RESTRICTED">Restrito</option></select></Field></div><div className="field-grid"><Field label="Criador / origem"><input value={creator} onChange={(event)=>setCreator(event.target.value)} placeholder="Quem criou este arquivo?"/></Field>{rights==="LICENSED"&&<Field label="Nome da licença"><input value={licenseName} onChange={(event)=>setLicenseName(event.target.value)} placeholder="Ex.: licença do banco de imagens"/></Field>}</div><Field label="URL da fonte (opcional)"><input type="url" value={sourceUrl} onChange={(event)=>setSourceUrl(event.target.value)} placeholder="https://…"/></Field><div className="upload-actions"><label className="small-note"><input type="checkbox" checked={commercialUse} onChange={(event)=>setCommercialUse(event.target.checked)}/> Uso comercial autorizado</label><button className="button primary" disabled={busy||!selected||(rights==="LICENSED"&&!licenseName.trim())} onClick={()=>void upload()}><Upload size={16}/> Importar para biblioteca</button></div>{uploadProgress&&<div className="ingest-feedback" role="status"><strong>Importando {uploadProgress.name}</strong><progress max={uploadProgress.total} value={uploadProgress.received}/><small>{Math.round(uploadProgress.received/1048576)} de {Math.round(uploadProgress.total/1048576)} MiB recebidos. Se interromper, selecione o mesmo arquivo para retomar.</small></div>}{lastProxyJob&&<p className="small-note" role="status">Original recebido. Proxy: {stateLabels[jobs.find((job)=>job.id===lastProxyJob)?.status??"QUEUED"]??"Na fila"}.</p>}</div></div>
    <div className="section-heading"><div><h2>Arquivos</h2><p>Transcrição offline disponível para áudio e vídeo.</p></div></div><div className="panel">{assets.length?assets.map((asset)=><div className="row library-row" key={asset.id}><span className="row-icon"><FolderOpen size={18}/></span><span className="row-main"><strong>{asset.name}</strong><small>{asset.media_type} · {asset.rights_status} · {Math.round((asset.metadata_json.size_bytes??0)/1024)} KB{asset.metadata_json.duration_ms?` · ${Math.round(asset.metadata_json.duration_ms/1000)} s`:""}{asset.metadata_json.ingest_status?` · ${ingestLabels[asset.metadata_json.ingest_status]??asset.metadata_json.ingest_status}`:""}</small></span>{asset.metadata_json.proxy_sha256&&<a className="button small" href={api.assetProxy(asset.id)} target="_blank" rel="noreferrer">Proxy</a>}{asset.metadata_json.waveform_sha256&&<a className="button small" href={api.assetWaveform(asset.id)} target="_blank" rel="noreferrer">Onda</a>}<a className="button small" href={api.assetFile(asset.id)} download>Baixar</a><button className="button small" onClick={()=>openRights(asset)}>Direitos</button>{(asset.media_type.startsWith("audio/")||asset.media_type.startsWith("video/"))&&<><button className="button small" onClick={()=>setTimedAsset(asset)}>Legendas</button>{asset.media_type.startsWith("video/")&&<button className="button small" onClick={()=>setClipAsset(asset)}>Cortes</button>}<button className="button small" disabled={busy||system?.transcription!=="AVAILABLE"} onClick={()=>void onRun(async()=>{await api.transcribe(asset.id);})}>Transcrever</button>{jobs.some((job)=>job.job_type==="TRANSCRIBE"&&job.result?.output?.includes(asset.id)&&job.status==="SUCCEEDED")&&<button className="button small" onClick={()=>void showTranscript(asset)}>Ver texto</button>}</>}</div>):<Empty icon={FolderOpen} text="Sua biblioteca ainda está vazia."/>}</div>{editingRights&&<div className="modal-backdrop" onMouseDown={(event)=>{if(event.target===event.currentTarget)setEditingRights(null);}}><form className="modal" onSubmit={(event)=>{event.preventDefault();void saveRights();}}><div className="eyebrow">DIREITOS DA MÍDIA</div><h2>{editingRights.name}</h2><Field label="Status"><select value={editStatus} onChange={(event)=>setEditStatus(event.target.value)}><option value="UNKNOWN">A verificar</option><option value="OWNED">Meu arquivo</option><option value="LICENSED">Licenciado</option><option value="RESTRICTED">Restrito</option></select></Field><Field label="Criador / origem"><input value={editCreator} onChange={(event)=>setEditCreator(event.target.value)}/></Field><Field label="URL da fonte"><input type="url" value={editSourceUrl} onChange={(event)=>setEditSourceUrl(event.target.value)}/></Field>{editStatus==="LICENSED"&&<Field label="Nome da licença"><input value={editLicense} onChange={(event)=>setEditLicense(event.target.value)} required/></Field>}<label className="small-note"><input type="checkbox" checked={editCommercial} onChange={(event)=>setEditCommercial(event.target.checked)}/> Uso comercial autorizado</label><div className="modal-actions"><button className="button" type="button" onClick={()=>setEditingRights(null)}>Cancelar</button><button className="button primary" type="submit" disabled={busy}>Salvar direitos</button></div></form></div>}{transcript!==null&&<div className="panel"><div className="panel-head"><h3>Transcrição · {transcriptName}</h3></div><div className="panel-body"><p style={{whiteSpace:"pre-wrap"}}>{transcript||"Nenhuma fala reconhecida."}</p></div></div>}{timedAsset&&<TimedTranscriptEditor asset={timedAsset} onClose={()=>setTimedAsset(null)} onRun={onRun}/>}{clipAsset&&<ClipMachine asset={clipAsset} onClose={()=>setClipAsset(null)} onRun={onRun}/>}</>;
}

function Channels({channels,busy,onCreate,onPilots,onRun}:{channels:Channel[];busy:boolean;onCreate:()=>void;onPilots:()=>void;onRun:(action:()=>Promise<unknown>)=>Promise<void>}) {
  const [editing,setEditing]=useState<string|null>(null);
  const [name,setName]=useState(""); const [tone,setTone]=useState(""); const [accent,setAccent]=useState("#c4d4ef"); const [autoRender,setAutoRender]=useState(false);
  const startEdit=(channel:Channel)=>{setEditing(channel.id);setName(channel.name);setTone(String(channel.editorial_profile.tone??""));setAccent(String(channel.brand_profile.accent??"#c4d4ef"));setAutoRender(channel.editorial_profile.auto_render===true);};
  return <><div className="section-heading no-top"><div><h2>Seus canais</h2><p>Configure a identidade visual e editorial de cada operação.</p></div><button className="button primary" onClick={onCreate}><Plus size={16}/> Novo canal</button></div>{!channels.length?<div className="panel empty"><Radio size={24}/>Você ainda não tem canais.<div className="empty-action"><button className="button primary" disabled={busy} onClick={()=>void onPilots()}>Criar os três canais piloto</button></div></div>:<div className="channel-grid">{channels.map((channel)=><div className="panel channel-card" key={channel.id}><div className="channel-icon" style={{borderColor:String(channel.brand_profile.accent??"#69798d")}}><Radio size={23}/></div><div className="eyebrow">{channel.default_engine.toUpperCase()} ENGINE</div><h3>{channel.name}</h3><p>{channel.niche} · {channel.language} · {channel.timezone}</p><div className="channel-card-bottom"><span className="badge green"><span className="live-dot"/> Canal local</span><button className="button small" onClick={()=>startEdit(channel)}>Configurar <ArrowRight size={13}/></button></div></div>)}</div>}{editing&&<div className="modal-backdrop" onMouseDown={(event)=>{if(event.target===event.currentTarget)setEditing(null);}}><form className="modal" onSubmit={(event)=>{event.preventDefault();void onRun(async()=>{const current=channels.find((channel)=>channel.id===editing);await api.updateChannel(editing,{name,brand_profile:{...current?.brand_profile,accent},editorial_profile:{...current?.editorial_profile,tone,auto_render:autoRender}});setEditing(null);});}}><div className="eyebrow">IDENTIDADE DO CANAL</div><h2>Configurar canal</h2><Field label="Nome"><input value={name} minLength={2} onChange={(event)=>setName(event.target.value)} required/></Field><Field label="Tom editorial"><input value={tone} onChange={(event)=>setTone(event.target.value)} placeholder="Ex.: informativo e direto"/></Field><Field label="Cor principal"><input value={accent} onChange={(event)=>setAccent(event.target.value)} pattern="#[0-9a-fA-F]{6}"/></Field><Field label="Automação local"><span><input type="checkbox" checked={autoRender} onChange={(event)=>setAutoRender(event.target.checked)}/> Renderizar automaticamente após gerar o plano</span></Field><div className="modal-actions"><button className="button" type="button" onClick={()=>setEditing(null)}>Cancelar</button><button className="button primary" type="submit" disabled={busy}><Save size={15}/> Salvar</button></div></form></div>}</>;
}

function DesktopServicePanel() {
  const [services,setServices]=useState<DesktopServices|null>(null);
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState<string|null>(null);
  useEffect(()=>{
    if(!runningInDesktop()) return;
    const refresh=()=>{void desktopServices().then(setServices).catch((reason)=>setError(message(reason)));};
    refresh();
    const timer=setInterval(refresh,5000);
    return ()=>clearInterval(timer);
  },[]);
  if(!runningInDesktop()) return null;
  const act=async(action:()=>Promise<unknown>)=>{setBusy(true);setError(null);try{await action();setServices(await desktopServices());}catch(reason){setError(message(reason));}finally{setBusy(false);}};
  return <div className="panel desktop-services"><div className="panel-head"><div><h3>Serviços do aplicativo</h3><p>Iniciados e monitorados pelo MediaGrid</p></div></div><div className="panel-body">{error&&<Alert text={error}/>}<div className="service-grid"><span>MediaGrid Core <Badge value={services?.core?"ONLINE":"OFFLINE"}/></span><span>Worker <Badge value={services?.worker?"ONLINE":"OFFLINE"}/></span><span>Banco local <Badge value={services?.database?"ONLINE":"OFFLINE"}/></span><span>Ollama <Badge value={services?.ollama?"ONLINE":"OFFLINE"}/></span></div><div className="editor-actions"><button className="button" disabled={busy||Boolean(services?.core&&services?.worker)} onClick={()=>void act(desktopStart)}>Iniciar</button><button className="button" disabled={busy||Boolean(!services?.core&&!services?.worker)} onClick={()=>void act(desktopStop)}>Parar</button><button className="button" disabled={busy} onClick={()=>void act(desktopRestart)}><RotateCcw size={15}/> Reiniciar</button><button className="button" onClick={()=>void desktopOpenLogs().catch((reason)=>setError(message(reason)))}>Abrir logs</button></div><p className="small-note">{services?.log_dir}</p></div></div>;
}

function DoctorPanel() {
  const [report,setReport]=useState<DoctorReport|null>(null);
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState<string|null>(null);
  const diagnose=async(internet=false)=>{setBusy(true);setError(null);try{setReport(await api.doctor(internet));}catch(reason){setError(message(reason));}finally{setBusy(false);}};
  useEffect(()=>{void diagnose();},[]);
  return <div className="panel doctor-panel"><div className="panel-head"><div><h3>Diagnóstico do sistema</h3><p>Verificação local dos componentes e permissões</p></div><button className="button small" disabled={busy} onClick={()=>void diagnose(true)}><RefreshCw size={14}/> Diagnosticar</button></div>{error&&<div className="panel-body"><Alert text={error}/></div>}{report?.checks.map((check)=><div className="row" key={check.id}><span className="row-main"><strong>{check.name}</strong><small>{check.detail}</small></span><Badge value={check.status}/></div>)}</div>;
}

function BackupPanel() {
  const [assets,setAssets]=useState(true);
  const [renders,setRenders]=useState(true);
  const [models,setModels]=useState(false);
  const [busy,setBusy]=useState(false);
  const [notice,setNotice]=useState<string|null>(null);
  const [error,setError]=useState<string|null>(null);
  if (!runningInDesktop()) return null;
  const backup=async()=>{setBusy(true);setError(null);setNotice(null);try{const path=await desktopCreateBackup({assets,renders,models});if(path)setNotice(`Backup salvo em ${path}`);}catch(reason){setError(message(reason));}finally{setBusy(false);}};
  const restore=async()=>{
    if (!window.confirm("Restaurar um backup substitui os dados atuais. Uma cópia dos dados anteriores será preservada. Continuar?")) return;
    setBusy(true);setError(null);setNotice(null);
    try{const previous=await desktopRestoreBackup();if(previous!==undefined){window.alert(previous?`Backup restaurado. Os dados anteriores estão em ${previous}`:"Backup restaurado.");window.location.reload();}}
    catch(reason){setError(message(reason));}finally{setBusy(false);}
  };
  return <div className="panel"><div className="panel-head"><div><h3>Backup portátil</h3><p>Guarde seus dados em um arquivo .mgrid neste computador ou em um disco externo.</p></div></div><div className="panel-body">{error&&<Alert text={error}/>} {notice&&<p className="small-note">{notice}</p>}<div className="wizard-facts"><label><input type="checkbox" checked={assets} onChange={(event)=>setAssets(event.target.checked)}/> Biblioteca</label><label><input type="checkbox" checked={renders} onChange={(event)=>setRenders(event.target.checked)}/> Vídeos e exportações</label><label><input type="checkbox" checked={models} onChange={(event)=>setModels(event.target.checked)}/> Modelos locais</label></div><p className="small-note">O banco, as configurações, vozes e transcrições sempre entram no backup. Os serviços pausam durante a operação.</p><div className="editor-actions"><button className="button" disabled={busy} onClick={()=>void backup()}><Save size={15}/> Exportar backup</button><button className="button" disabled={busy} onClick={()=>void restore()}><FolderOpen size={15}/> Restaurar backup</button></div></div></div>;
}

function SettingsView({setup,hardware,system,onNavigate}:{setup:SetupState;hardware:HardwareProfile|null;system:SystemStatus|null;onNavigate:(view:View)=>void}) {return <><div className="premium-page-heading"><div><div className="eyebrow">08 / LOCAL SETTINGS</div><h2>Seu estúdio, suas regras.</h2><p>Serviços, desempenho, dados e diagnósticos deste computador.</p></div></div><div className="settings-summary"><div><span>PERFIL</span><strong>{setup.profile??"Não configurado"}</strong></div><div><span>PASTA DE DADOS</span><strong>{setup.data_dir}</strong></div><div><span>IA LOCAL</span><strong>{system?.ollama==="CONNECTED"?"Ollama conectado":"Não conectada"}</strong></div><div><span>MEMÓRIA</span><strong>{hardware?.ram_gb!=null?`${hardware.ram_gb} GB`:"Não detectada"}</strong></div></div><div className="atelier-toolbar"><button className="button" onClick={()=>onNavigate("library")}><FolderOpen size={15}/> Biblioteca local</button><button className="button" onClick={()=>onNavigate("control")}><Activity size={15}/> Fila e trabalhos</button></div><DesktopServicePanel/><DoctorPanel/><BackupPanel/></>}

function SystemView({system,jobs,busy,onRun}:{system:SystemStatus|null;jobs:Job[];busy:boolean;onRun:(action:()=>Promise<unknown>)=>Promise<void>}) {return <><div className="section-heading no-top"><div><h2>Estado do sistema local</h2><p>Todos os serviços da V1 executam neste computador.</p></div></div><DesktopServicePanel/><DoctorPanel/><BackupPanel/><div className="metric-grid"><Metric label="Modo" value={system?.mode??"—"} detail="Acesso por localhost" icon={Activity}/><Metric label="FFmpeg" value={system?.ffmpeg?"Ativo":"Indisponível"} detail="Vídeo local" icon={Film}/><Metric label="Ollama" value={system?.ollama==="CONNECTED"?"Conectado":"Opcional"} detail="IA local" icon={Cpu}/><Metric label="Banco" value={system?.database??"—"} detail="Dados no computador" icon={Radio}/><Metric label="Voz" value={system?.tts==="AVAILABLE"?"Disponível":"Configurar"} detail="Síntese offline" icon={Mic}/><Metric label="Transcrição" value={system?.transcription==="AVAILABLE"?"Disponível":"Configurar"} detail="Reconhecimento offline" icon={Mic}/></div><div className="section-heading"><div><h2>Fila local</h2><p>O worker processa trabalhos e faz backup diário do banco em data/backups.</p></div></div><div className="panel">{jobs.length?jobs.map((job)=><div key={job.id} className="row"><span className="row-icon"><Film size={18}/></span><span className="row-main"><strong>{job.job_type} · {job.project_id?.slice(0,8)}</strong><small>{job.error??new Date(job.created_at).toLocaleString("pt-BR")}</small></span><Badge value={job.status}/>{job.status==="FAILED"&&job.attempt<job.max_attempts&&<button className="button small" disabled={busy} onClick={()=>void onRun(async()=>{await api.retry(job.id);})}><RotateCcw size={14}/> Repetir</button>}</div>):<Empty icon={Activity} text="Nenhum trabalho na fila."/>}</div><p className="small-note footer-note">A publicação em redes sociais permanece manual na V1. Nenhuma conta externa é necessária.</p></>}

function Metric({label,value,detail,icon:Icon}:{label:string;value:string;detail:string;icon:typeof Radio}) {return <div className="metric"><div className="metric-top"><span>{label.toUpperCase()}</span><Icon size={17}/></div><strong>{value}</strong><small>{detail}</small></div>}
function Badge({value}:{value:string}) {return <span className={`badge ${["QC","APPROVED","SUCCEEDED","ONLINE","READY"].includes(value)?"green":["FAILED","OFFLINE","ERROR","MISSING"].includes(value)?"orange":""}`}>{stateLabels[value]??value}</span>}
function Empty({icon:Icon,text}:{icon:typeof Radio;text:string}) {return <div className="empty"><Icon size={25}/>{text}</div>}
function Field({label,children}:{label:string;children:React.ReactNode}) {return <label className="field">{label}{children}</label>}
function Alert({text}:{text:string}) {return <div className="alert"><CircleAlert size={17}/>{text}</div>}
function Brand() {return <div className="brand static"><img className="brand-symbol" src="/brand-mark.svg" alt=""/><span className="brand-text"><strong>MediaGrid</strong><small>CONTENT OPERATING SYSTEM</small></span></div>}
function message(reason:unknown) {return reason instanceof Error?reason.message:"Ocorreu um erro. Tente novamente.";}
